SELECT id, msg_type AS msgType, title, content, CAST(is_read AS SIGNED) AS isRead, channel, create_time AS createTime
FROM sys_message
WHERE phone = #{phone}
ORDER BY create_time DESC
LIMIT #{offset}, #{size}

SELECT id, msg_type AS msgType, title, content, CAST(is_read AS SIGNED) AS isRead, channel, create_time AS createTime
FROM sys_message
WHERE user_id = #{userId}
ORDER BY create_time DESC
LIMIT #{offset}, #{size}
